sql.insert:
INSERT INTO equipment (
  equipment_id, slot_type, name_key, home_image_path, photo_image_path,
  list_icon_image_path, detail_icon_image_path, is_initial_owned, sort_order
) VALUES (
  @equipment_id, @slot_type, @name_key, @home_image_path, @photo_image_path,
  @list_icon_image_path, @detail_icon_image_path, @is_initial_owned, @sort_order
)
ON CONFLICT(equipment_id) DO UPDATE SET
  slot_type = excluded.slot_type,
  name_key = excluded.name_key,
  home_image_path = excluded.home_image_path,
  photo_image_path = excluded.photo_image_path,
  list_icon_image_path = excluded.list_icon_image_path,
  detail_icon_image_path = excluded.detail_icon_image_path,
  is_initial_owned = excluded.is_initial_owned,
  sort_order = excluded.sort_order;
